using Omnia.Metadata.Core;
namespace Omnia.Metadata.App;
public sealed class MainForm : Form
{
    readonly ListBox files = new() { Dock = DockStyle.Fill }; readonly RichTextBox report = new() { Dock = DockStyle.Fill, ReadOnly = true, BackColor = Color.White }; readonly FileAnalyzer analyzer = new(); AnalysisReport? current; readonly EntitlementState access;
    public MainForm(string authenticatedEmail, string role, string plan, int monthlyFreeQueriesUsed, int oneOffQueriesAvailable) { var edition = role.Equals("owner", StringComparison.OrdinalIgnoreCase) || plan.Equals("owner", StringComparison.OrdinalIgnoreCase) ? AppEdition.Proprietario : plan.Equals("subscriber", StringComparison.OrdinalIgnoreCase) ? AppEdition.Assinante : AppEdition.Free; access = new(edition, monthlyFreeQueriesUsed, oneOffQueriesAvailable); Text = "Omnia Metadata — " + edition + " — " + authenticatedEmail; Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath); Width = 1100; Height = 700; MinimumSize = new(800, 500); var open = new Button { Text = "Selecionar arquivo", AutoSize = true }; var export = new Button { Text = "Exportar .txt", AutoSize = true, Enabled = false }; var ai = new Button { Text = "Detecção de IA", AutoSize = true }; var textAi = new Button { Text = "Detecção de IA em texto", AutoSize = true }; var edit = new Button { Text = "Detecção de edição de mídia", AutoSize = true }; var about = new Button { Text = "Sobre", AutoSize = true }; open.Click += async (_, _) => await OpenFile(); export.Click += (_, _) => Export(); ai.Click += (_, _) => ShowCategory("IA e proveniência", "Detecção de IA"); textAi.Click += (_, _) => ShowTextAi(); edit.Click += (_, _) => ShowCategory("Edição e processamento", "Detecção de edição de mídia"); about.Click += (_, _) => ShowAbout(); var top = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 110, Padding = new(8), Controls = { open, export, ai, textAi, edit, about, new Label { Text = access.QueryMessage, AutoSize = true, Padding = new(8, 6, 0, 0) } } }; files.SelectedIndexChanged += (_, _) => { if (files.SelectedItem is string p) _ = Analyze(p, export); }; var split = new SplitContainer { Dock = DockStyle.Fill, SplitterDistance = 300, Panel1 = { Controls = { files } }, Panel2 = { Controls = { report } } }; Controls.Add(split); Controls.Add(top); report.Text = "Usuário autenticado: " + authenticatedEmail + "\n\nPlano: " + edition + "\n\nSelecione um arquivo para iniciar a análise local.\n\nNenhum arquivo é enviado para a nuvem nesta versão de validação."; }
    async Task OpenFile() { using var d = new OpenFileDialog { Filter = "Todos os arquivos|*.*", Multiselect = true }; if (d.ShowDialog() == DialogResult.OK) foreach (var p in d.FileNames) files.Items.Add(p); await Task.CompletedTask; }
    async Task Analyze(string path, Button export) { try { report.Text = "Analisando localmente…"; current = await analyzer.AnalyzeAsync(path); var filtered = current with { Fields = ReportAccessFilter.Apply(current.Fields, access) }; current = filtered; report.Text = ReportExporter.ToText(current); export.Enabled = true; } catch (Exception ex) { report.Text = "Análise inconclusiva.\n\nErro técnico: " + ex.Message; export.Enabled = false; } }
    void Export() { if (current is null) return; using var d = new SaveFileDialog { Filter = "Relatório TXT|*.txt", FileName = current.FileName + ".txt" }; if (d.ShowDialog() == DialogResult.OK) File.WriteAllText(d.FileName, ReportExporter.ToText(current)); }
    void ShowCategory(string category, string title) { if (current is null) { MessageBox.Show("Selecione e analise um arquivo primeiro.", title, MessageBoxButtons.OK, MessageBoxIcon.Information); return; } var items = current.Fields.Where(f => f.Name.Equals(category, StringComparison.OrdinalIgnoreCase) || (category.StartsWith("IA") && (f.Name.Contains("IA") || f.Name.Contains("proveniência", StringComparison.OrdinalIgnoreCase))) || (category.StartsWith("Edição") && f.Name.Contains("Edição", StringComparison.OrdinalIgnoreCase))).ToList(); report.Text = title.ToUpperInvariant() + Environment.NewLine + Environment.NewLine + (items.Count == 0 ? "Análise inconclusiva. Não há dados específicos suficientes." : string.Join(Environment.NewLine, items.Select(f => $"[{f.Kind}] {f.Name}: {f.Value}"))) + Environment.NewLine + Environment.NewLine + "A ausência de indícios não prova autenticidade."; }
    void ShowAbout() { MessageBox.Show("Omnia Metadata — Metadados de Arquivos\nVersão: 0.7.1\nEdição: " + access.Edition + "\n\nAnálise local técnica de metadados e integridade.\nA detecção textual combina sinais linguísticos, estatísticos e estruturais.\nResultados de IA e edição são indícios, não conclusões absolutas.", "Sobre", MessageBoxButtons.OK, MessageBoxIcon.Information); }
    void ShowTextAi() { var limit = access.Edition == AppEdition.Free ? 1000 : 20000; using var dialog = new Form { Text = "Detecção de IA em texto", Width = 700, Height = 500, StartPosition = FormStartPosition.CenterParent }; var input = new TextBox { Multiline = true, ScrollBars = ScrollBars.Vertical, Dock = DockStyle.Fill, MaxLength = limit }; var go = new Button { Text = "Analisar texto", Dock = DockStyle.Bottom, Height = 38 }; var info = new Label { Text = $"Cole até {limit:N0} caracteres. Triagem composta; não é prova de autoria.", Dock = DockStyle.Top, Height = 34 }; dialog.Controls.Add(input); dialog.Controls.Add(go); dialog.Controls.Add(info); go.Click += (_, _) => { var a = TextAiDetector.Assess(input.Text); MessageBox.Show($"{a.Classification}\nPontuação composta: {a.Score}/12\n\n{string.Join("\n", a.Signals)}\n\n{a.Limitation}", "Detecção de IA em texto", MessageBoxButtons.OK, MessageBoxIcon.Information); }; dialog.ShowDialog(this); }
}
